import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
# extract grids
def load():
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
from collections import Counter
print(Counter(v for r in inp for v in r))
# find solid rectangles per color
def blocks(g):
    h,w=len(g),len(g[0])
    seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; stack=[(i,j)]; comp=[]
                seen.add((i,j))
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and (ny,nx) not in seen:
                                seen.add((ny,nx)); stack.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                res.append((c,len(comp),min(ys),max(ys),min(xs),max(xs)))
    return res
for b in blocks(inp): print(b)
print(out)
